import{_ as e,a as o,b as a,c as i,d as s,e as n}from"./chunks/site-tools-options.CSfW-Ynq.js";import{_ as r,o as l,c as d,a2 as h}from"./chunks/framework.CfwCq2QB.js";const y=JSON.parse('{"title":"Site tools & recording","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/site-tools.md","filePath":"en/features/site-tools.md"}'),c={name:"en/features/site-tools.md"};function u(p,t,g,m,w,f){return l(),d("div",null,[...t[0]||(t[0]=[h('<h1 id="site-tools-recording" tabindex="-1">Site tools &amp; recording <a class="header-anchor" href="#site-tools-recording" aria-label="Permalink to &quot;Site tools &amp; recording&quot;">​</a></h1><p>In one line: add tools the AI assistant can call to any website — &quot;search products on this site&quot;, &quot;read my order list&quot;, &quot;fill in this form and submit&quot;. Let the AI build one by looking at the page, or record your own actions once; saved tools can be replayed with one click or called automatically by the AI in chat.</p><p>How this differs from <a href="/dev-go-docs/en/features/webmcp.html">Page tools (WebMCP)</a>: WebMCP tools are provided by the site itself, and most sites don&#39;t have any yet. Site tools are ones you add yourself — they work on any site and don&#39;t need the browser&#39;s experimental flag.</p><h2 id="option-1-let-the-ai-build-it" tabindex="-1">Option 1: let the AI build it <a class="header-anchor" href="#option-1-let-the-ai-build-it" aria-label="Permalink to &quot;Option 1: let the AI build it&quot;">​</a></h2><ol><li>Open the site, open the side panel (<code>Alt+2</code>) and switch to &quot;<strong>Page tools</strong>&quot;</li><li>If the site has no tools yet, the page shows a &quot;What tool do you need?&quot; box right away; otherwise click &quot;<strong>New tool with AI</strong>&quot;</li><li>Describe what you need, or click one of the examples (&quot;Search this site and return titles and links&quot;, &quot;Read the list data on this page&quot;, …), then click &quot;<strong>Create</strong>&quot;</li><li>Follow along in chat: the AI <strong>inspects the page</strong> → writes the tool → <strong>test-runs</strong> it, fixing mistakes on its own</li><li>Before saving, a confirmation card shows the full tool definition; nothing is saved until you click &quot;Allow&quot;</li></ol><img src="'+e+'" alt="The side panel&#39;s Page tools page with no tools: an explanation and a &#39;What tool do you need?&#39; box with three examples and a Create button (Chinese UI)" style="width:40%;display:block;margin-left:auto;margin-right:auto;"><p><em>The Page tools page: with no tools yet, describe what you need and let the AI build it (Chinese UI).</em></p><p>You can also just say &quot;make a search tool for this site&quot; in Chat — same result.</p><h2 id="option-2-record-your-actions" tabindex="-1">Option 2: record your actions <a class="header-anchor" href="#option-2-record-your-actions" aria-label="Permalink to &quot;Option 2: record your actions&quot;">​</a></h2><p>Best for step-by-step flows (&quot;click here, pick that, fill this in, submit&quot;). You do it once by hand, so the steps are exact — no AI involved, and it works even without a model configured.</p><p><strong>Start recording</strong>: click &quot;Record&quot; on the &quot;Record actions&quot; row of the popup&#39;s Features tab, or &quot;<strong>Record actions</strong>&quot; on the side panel&#39;s Page tools page.</p><img src="'+o+'" alt="The Record actions row on the popup&#39;s Features tab, with a Record button marked by a red dot (Chinese UI)" style="width:60%;display:block;margin-left:auto;margin-right:auto;"><p><em>The &quot;Record actions&quot; entry on the popup&#39;s Features tab (Chinese UI).</em></p><p><strong>While recording</strong>: a recording bar appears at the top of the page. Just use the page:</p><ul><li>Clicks, typing, checkboxes, dropdowns and Enter are recorded; repeated typing in one field keeps only the final value</li><li>Recording continues across page navigations (e.g. home → login → account)</li><li>To make the tool return data, click &quot;<strong>Pick data</strong>&quot; on the bar, click the content to read, and choose &quot;Read this item&quot; or &quot;Read the whole list (N items)&quot; — similar list items are detected automatically</li><li>Click &quot;<strong>Done</strong>&quot; to finish (or &quot;Finish&quot; in the popup); &quot;Cancel&quot; discards the recording</li></ul><img src="'+a+'" alt="A page being recorded: the recording bar at the top (Recording · 5 steps / Pick data / Cancel / Done); an item in the order list is picked, offering Read this item / Read the whole list (3 items) (Chinese UI)"><p><em>The recording bar and &quot;Pick data&quot;: clicking an order offers to read that item or the whole list (Chinese UI).</em></p><p><strong>Review and save</strong>: when you finish, the side panel opens a review page:</p><ul><li>Tick &quot;<strong>Make it a parameter</strong>&quot; next to any entered value so it can change next time (a search keyword, a username)</li><li>Edit the tool name, the description (the AI uses it to decide when to call the tool) and the sites it applies to</li><li>&quot;<strong>Read-only</strong>&quot;: turn on for flows that only read and don&#39;t change data; they then run without confirmation (off by default)</li><li>&quot;<strong>Open the starting URL first</strong>&quot;: every run first goes to where recording started (off by default — runs on the current page)</li><li>Remove any unwanted steps; &quot;<strong>Test run</strong>&quot; to check (a test run always returns to the starting URL first), then &quot;<strong>Save</strong>&quot;</li></ul><img src="'+i+'" alt="The recording review page: tool name, description, sites, the Read-only and Open the starting URL first switches, and six steps; the username is a parameter and the password wasn&#39;t recorded (Chinese UI)" style="width:40%;display:block;margin-left:auto;margin-right:auto;"><p><em>The review page: the username is made a parameter; the password wasn&#39;t recorded and is passed in at run time (Chinese UI).</em></p><h3 id="passwords" tabindex="-1">Passwords <a class="header-anchor" href="#passwords" aria-label="Permalink to &quot;Passwords&quot;">​</a></h3><p>Passwords are <strong>not recorded</strong> by default: a recorded password field becomes a parameter that&#39;s passed in when the tool runs. If you really want them saved for convenience, turn on &quot;<strong>Save passwords when recording</strong>&quot; under Settings → AI assistant → Site tools. Passwords are then stored in plain text in the local tool definition and included in backup files — weigh that before enabling it.</p><h2 id="using-tools" tabindex="-1">Using tools <a class="header-anchor" href="#using-tools" aria-label="Permalink to &quot;Using tools&quot;">​</a></h2><ul><li><strong>Let the AI call them</strong>: on that site, just ask — &quot;find keyboards and list them by price&quot; — and the AI calls the matching site tool</li><li><strong>Run manually</strong>: on the side panel&#39;s Page tools page, site tools carry a &quot;Site tool&quot; badge; expand a card, fill in arguments and click &quot;Run&quot;</li></ul><img src="'+s+'" alt="Side panel chat: the user asks to search keyboards, the AI calls search_products and lists three products with prices and links in a table (Chinese UI)" style="width:40%;display:block;margin-left:auto;margin-right:auto;"><p><em>The AI calling a site tool in chat and presenting the result as a table (Chinese UI).</em></p><p>Tools that may change data (not marked read-only) ask for confirmation before running — the same switch as for page tools (Settings → AI assistant).</p><h2 id="managing-importing-and-exporting" tabindex="-1">Managing, importing and exporting <a class="header-anchor" href="#managing-importing-and-exporting" aria-label="Permalink to &quot;Managing, importing and exporting&quot;">​</a></h2><p>Settings → <strong>AI assistant → Site tools</strong> lists every site tool. You can:</p><ul><li>Enable / disable, edit (as JSON), or delete them</li><li><strong>Export</strong> a tool as a JSON file to share it</li><li><strong>Import</strong> tools exported from DevGo, or JSON recordings exported from the <strong>Chrome DevTools Recorder</strong> panel — existing recordings become site tools directly</li></ul><p>Site tools are included in <a href="/dev-go-docs/en/settings/sync.html">backups</a>.</p><img src="'+n+'" alt="The Site tools card in Settings: Import and New buttons, one imported recording with enable switch, edit, export and delete buttons, and the Save passwords when recording switch below (Chinese UI)"><p><em>The Site tools card in Settings: import / export, enable switches and &quot;Save passwords when recording&quot; (Chinese UI).</em></p><h2 id="how-it-works-limits" tabindex="-1">How it works &amp; limits <a class="header-anchor" href="#how-it-works-limits" aria-label="Permalink to &quot;How it works &amp; limits&quot;">​</a></h2><ul><li>A tool is <strong>pure data</strong>: a few parameters plus fixed steps (call an API, fill, press a key, click, wait, read, open a URL), run by DevGo&#39;s built-in executor. <strong>No code is executed</strong>, no extra permissions are needed, and it works on sites with strict security policies such as GitHub</li><li>Each element is saved with 3–5 candidate selectors (by name, attributes, text, path), so small site changes fall back automatically; actions wait for their element to appear first</li><li>Multi-page flows work: when a click or URL causes navigation, the remaining steps continue once the new page has loaded</li><li>Tools work right after DevGo is installed or updated, without refreshing open pages</li><li>Not supported yet: elements inside iframes, drag / hover / scroll. After a big site redesign selectors may break — ask the AI to &quot;fix this tool&quot;, or record it again</li><li>Sites are matched by domain (<code>github.com</code>, including subdomains) or a wildcard path (<code>github.com/*/issues*</code>); tools only appear on matching sites</li></ul>',36)])])}const k=r(c,[["render",u]]);export{y as __pageData,k as default};
